mapper.select:
SELECT p.id, m.merchant_name AS merchantName, p.product_name AS productName, p.product_image_url AS productImageUrl, p.price, p.stock, p.original_price AS originalPrice, p.sku, p.status, p.sales_count AS salesCount, p.view_count AS viewCount, p.created_at AS createdAt, p.updated_at AS updatedAt FROM product p LEFT JOIN merchant m ON p.merchant_id = m.merchant_id
AND p.is_deleted = 0
AND p.id = #{backgroundGetProductByConditionDTO.id}
AND m.merchant_name LIKE CONCAT('%', #{backgroundGetProductByConditionDTO.merchantName}, '%')
AND p.product_name LIKE CONCAT('%', #{backgroundGetProductByConditionDTO.productName}, '%')
AND p.sku = #{backgroundGetProductByConditionDTO.sku}
AND p.status = #{backgroundGetProductByConditionDTO.status}
ORDER BY p.created_at DESC

SELECT DISTINCT p.id, p.product_name AS productName, p.merchant_id AS merchantId, m.merchant_name AS merchantName, p.product_image_url AS productImageUrl, p.price, p.stock, p.is_hot AS isHot, p.is_new AS isNew, p.rating, p.sales_count AS salesCount, p.view_count AS viewCount FROM product p LEFT JOIN merchant m ON p.merchant_id = m.merchant_id LEFT JOIN product_category pc ON p.id = pc.product_id
-- 商品状态：上架且未删除 p.status = 1 AND p.is_deleted = 0 -- 商家状态：正常且未删除 AND m.status = 1 AND m.is_deleted = 0
AND p.product_name LIKE CONCAT('%', #{query.productName}, '%')
AND pc.category_id = #{query.categoryId}
AND m.merchant_name LIKE CONCAT('%', #{query.merchantName}, '%')
-- Boolean 类型在 MyBatis 中会被转换为 1 (true) 或 0 (false) AND p.is_hot = #{query.isHot}
AND p.is_new = #{query.isNew}
ORDER BY
/* 当销量排序为 true 时，按销量降序 */ p.sales_count DESC
/* 当价格排序为 true 时，按价格升序 */ p.price ASC
/* 当浏览量排序为 true 时，按浏览量降序 */ p.view_count DESC
/* 默认排序：按创建时间降序 */ p.created_at DESC
